# =================================================================
# AEGIS NIDS - Phase 3 Best Practices Deployment
# =================================================================
# Fixes: 12 Medium + 3 Low severity
#
# M3:  bridge_init.zig: all init/shutdown messages -> std.log (release visible)
# M4:  sensor files: BLOCK/ALERT security events -> std.log
# M5:  nids_analyze.zig: ctrlHandler/Rules.json/pipe spawn -> std.log
# M6:  bridge pushEvent failures now logged (was silent discard)
# M7:  inspect_packet errors in pipe/TCP handlers now logged
# M9:  Named constant MAX_CONCURRENT_CONNECTIONS replaces magic 100
# M10: nids_capture.zig ACL failure -> std.log.warn
# M11: bridge_init summary -> std.log.info
# M12: "64KB" string -> ANALYZE_MAX_PAYLOAD constant in log
# L8:  Magic 90 -> MAX_CONCURRENT_CONNECTIONS * 9 / 10
# L9:  Removed redundant SetConsoleCtrlHandler registration
# L15: wfp_ioctl blocked IP table-full -> std.log.warn
# L16: bridge_init shutdown banner -> std.log.info
# =================================================================

$ErrorActionPreference = "Stop"
$DeployRoot = Split-Path -Parent $MyInvocation.MyCommand.Path

Write-Host "[DEPLOY] AEGIS Phase 3 Best Practices Fix" -ForegroundColor Cyan
Write-Host "[DEPLOY] Deploy root: $DeployRoot" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path (Join-Path $DeployRoot "core"))) {
    Write-Host "  [ERROR] core/ directory not found" -ForegroundColor Red
    exit 1
}

$backupDir = Join-Path $DeployRoot "backups_phase3"
if (-not (Test-Path $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

# =================================================================
# FILE 1/7: core/nids_analyze.zig (1600 lines)
# M3/M5/M6/M7/M9/M12/L8/L9: std.log + named constants + error logging
# =================================================================

Write-Host "[1/7] Deploying core/nids_analyze.zig..." -ForegroundColor Yellow

$src1 = Join-Path $DeployRoot "core/nids_analyze.zig"
if (-not (Test-Path $src1)) {
    Write-Host "  [ERROR] Source not found: $src1" -ForegroundColor Red
    exit 1
}

Copy-Item $src1 (Join-Path $backupDir "core_nids_analyze.zig.bak") -Force
Write-Host "  [OK] Backup created" -ForegroundColor Green

