$verify7 = (Get-Content $src7 -Encoding UTF8).Count
if ($verify7 -ne 419) {
    Write-Host "  [ERROR] Line count mismatch: expected 419, got $verify7" -ForegroundColor Red
    Copy-Item (Join-Path $backupDir "core_wfp_ioctl.zig.bak") $src7 -Force
    exit 1
}
Write-Host "  [OK] Deployed: $verify7 lines (expected 419)" -ForegroundColor Green

Write-Host "[BUILD] Running zig build..." -ForegroundColor Cyan

$buildOutput = & zig build 2>&1
$buildExit = $LASTEXITCODE

if ($buildExit -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 3 fixes applied" -ForegroundColor Green
    Write-Host ""
    Write-Host "Summary of changes:" -ForegroundColor Cyan
    Write-Host "  M3:  bridge_init: 15 std.log calls for release-build visibility" -ForegroundColor White
    Write-Host "  M4:  4 sensor files: security BLOCK/ALERT -> std.log" -ForegroundColor White
    Write-Host "  M5:  nids_analyze: 3 critical messages -> std.log" -ForegroundColor White
    Write-Host "  M6:  pushEvent failures logged (was silent discard)" -ForegroundColor White
    Write-Host "  M7:  inspect_packet errors in pipe/TCP now logged" -ForegroundColor White
    Write-Host "  M9:  MAX_CONCURRENT_CONNECTIONS constant replaces 100" -ForegroundColor White
    Write-Host "  M10: Pipe ACL failure -> std.log.warn" -ForegroundColor White
    Write-Host "  M11: Bridge init summary -> std.log.info" -ForegroundColor White
    Write-Host "  M12: ANALYZE_MAX_PAYLOAD constant in log message" -ForegroundColor White
    Write-Host "  L8:  Semaphore 90 -> MAX_CONCURRENT_CONNECTIONS*9/10" -ForegroundColor White
    Write-Host "  L9:  Redundant SetConsoleCtrlHandler removed" -ForegroundColor White
    Write-Host "  L15: Blocked IP table-full -> std.log.warn" -ForegroundColor White
    Write-Host "  L16: Bridge shutdown banner -> std.log.info" -ForegroundColor White
    Write-Host ""
    Write-Host "Suggested git commands:" -ForegroundColor Cyan
    Write-Host "  git add -A" -ForegroundColor White
    Write-Host "  git commit -m "fix: best practices phase 3 - medium severity"" -ForegroundColor White
    Write-Host "  git push" -ForegroundColor White
    Write-Host ""

    Remove-Item -Recurse -Force $backupDir -ErrorAction SilentlyContinue
} else {
    Write-Host "[BUILD] FAILED (exit code $buildExit)" -ForegroundColor Red
    Write-Host ""
    Write-Host "Build output:" -ForegroundColor Yellow
    Write-Host $buildOutput
    Write-Host ""
    Write-Host "Rolling back all files..." -ForegroundColor Yellow

    Copy-Item (Join-Path $backupDir "core_nids_analyze.zig.bak") Join-Path $DeployRoot "core/nids_analyze.zig" -Force
    Copy-Item (Join-Path $backupDir "core_bridge_init.zig.bak") Join-Path $DeployRoot "core/bridge_init.zig" -Force
    Copy-Item (Join-Path $backupDir "core_nids_capture.zig.bak") Join-Path $DeployRoot "core/nids_capture.zig" -Force
    Copy-Item (Join-Path $backupDir "core_pipe_monitor.zig.bak") Join-Path $DeployRoot "core/pipe_monitor.zig" -Force
    Copy-Item (Join-Path $backupDir "core_windows_capture.zig.bak") Join-Path $DeployRoot "core/windows_capture.zig" -Force
    Copy-Item (Join-Path $backupDir "core_minifilter_reader.zig.bak") Join-Path $DeployRoot "core/minifilter_reader.zig" -Force
    Copy-Item (Join-Path $backupDir "core_wfp_ioctl.zig.bak") Join-Path $DeployRoot "core/wfp_ioctl.zig" -Force

    Write-Host "[ROLLBACK] All files restored from backups" -ForegroundColor Yellow
    exit 1
}